## Why This Is Asked

Tests understanding of streaming architectures under load, including partitioning, backpressure, and correctness guarantees (exactly-once) in the presence of late data and failures.

## Key Concepts

- Backpressure and bounded queues
- Partitioning by key for ordering guarantees
- Watermarks and late-data handling
- Windowed aggregations and state management
- Exactly-once semantics via checkpointing and replay
- Test strategies for bursts, late data, and crash recovery

## Code Example

```javascript
// Pseudo-code: per-partition window with watermark and late path
class PartitionProcessor {
  constructor(sensorId, queueCapacity = 1000) {
    this.sensorId = sensorId;
    this.queue = new BoundedQueue(queueCapacity);
    this.window = new TumblingWindow(5000); // 5s window
    this.watermark = new MonotonicWatermark();
    this.lateBuffer = new LateDataBuffer();
  }

  process(event) {
    if (event.timestamp < this.watermark.get()) {
      this.lateBuffer.add(event);
      return;
    }

    if (this.queue.isFull()) {
      this.signalBackpressure();
      return false;
    }

    this.queue.add(event);
    this.watermark.update(event.timestamp);
    this.window.add(event);

    if (this.window.isReady()) {
      this.emitAggregates();
      this.window.reset();
    }
  }
}
```

## Why This Is Asked

This question tests real-world concurrency understanding: preserving per-region ordering under backpressure, implementing fairness across regions, and enabling dynamic worker resizing without breaking guarantees.

## Key Concepts

- **Per-region ordering**: Monotonic counters ensure events within each region maintain FIFO order across all pipeline stages
- **Bounded queues and backpressure**: Backpressure signaling prevents memory exhaustion when producers outpace consumers
- **Regional fairness scheduler**: Weighted round-robin allocates processing slots proportionally to region weights
- **Dynamic worker resizing**: Per-region worker pools can scale independently without violating ordering guarantees
- **Late/out-of-order event handling**: Watermark-based windowing and retries for events arriving after their expected timestamp

## Code Example

```javascript
class RegionBuffer {
  constructor(limit) {
    this.queue = [];
    this.limit = limit;
    this.nextSeq = 0;
  }

  enqueue(event) {
    if (this.queue.length >= this.limit) {
      throw new BackpressureError('region buffer full');
    }
    event.seq = this.nextSeq++;
    this.queue.push(event);
    return event;
  }

  dequeue() {
    return this.queue.shift();
  }

  isFull() {
    return this.queue.length >= this.limit;
  }
}

class RegionalFairnessScheduler {
  constructor(regions, weights) {
    this.regionBuffers = new Map();
    this.weights = weights;
    this.counters = new Map();
    this.currentIndex = 0;

    regions.forEach(region => {
      this.regionBuffers.set(region, new RegionBuffer(1000));
      this.counters.set(region, 0);
    });
  }

  schedule() {
    const regions = Array.from(this.regionBuffers.keys());
    const weight = this.weights[regions[this.currentIndex]] || 1;

    if (this.counters.get(regions[this.currentIndex]) < weight) {
      const buffer = this.regionBuffers.get(regions[this.currentIndex]);
      if (buffer.queue.length > 0) {
        this.counters.set(regions[this.currentIndex], 
          this.counters.get(regions[this.currentIndex]) + 1);
        return buffer.dequeue();
      }
    }

    this.currentIndex = (this.currentIndex + 1) % regions.length;
    if (this.counters.get(regions[this.currentIndex]) >= weight) {
      this.counters.set(regions[this.currentIndex], 0);
    }
    return null;
  }
}
```

## Test Plan

### 1. Burst Handling Test
- Send 10x normal load from a single region
- Verify other regions still receive processing slots
- Confirm no starvation occurs

### 2. Late Events Test
- Introduce events with out-of-sequence timestamps
- Configure late-tolerance window (e.g., 5 seconds)
- Verify late events are handled according to policy (drop/retry/reject)

### 3. Backpressure Test
- Fill regional buffers to capacity
- Verify backpressure signal is emitted to producers
- Confirm producers throttle correctly
- Test backpressure release when buffer drains

### 4. Dynamic Worker Resizing Test
- Increase worker count mid-operation for a region
- Verify ordering maintained through the transition
- Decrease workers and confirm graceful degradation

### 5. Recovery Test
- Simulate region failure and recovery
- Confirm ordering guarantees restore after recovery

## Why This Is Asked

This question evaluates practical concurrency control under heavy load, enforcing per-team ordering with a global bottleneck and deterministic degradation. It assesses backpressure signaling, dynamic policy design, and test plan creation for real-world streaming workloads.

## Key Concepts

- Bounded global queue with capacity enforcement
- Per-team FIFO buffers maintaining sequence order
- Backpressure signaling mechanism to upstream producers
- Deterministic drop policy by severity level
- Ordering guarantees under graceful degradation
- Comprehensive test strategy for correctness and resilience

## Data Structures

```javascript
// Core types
type LogLevel = 'INFO' | 'WARN' | 'ERROR';
type Log = { teamId: string; severity: LogLevel; timestamp: number; payload: any; seq: number };

// Per-team FIFO buffer with sequence tracking
class TeamBuffer {
  constructor(teamId, capacity) {
    this.teamId = teamId;
    this.buffer = [];  // Circular buffer or ring buffer
    this.seq = 0;       // Monotonic sequence number
    this.criticalSeq = 0;  // Highest preserved ERROR/WARN seq
  }

  push(log) {
    log.seq = this.seq++;
    this.buffer.push(log);
  }

  // Deterministic drop: remove oldest non-critical when over capacity
  prune(threshold) {
    // Keep all ERROR, keep most recent WARN, drop oldest INFO
  }
}

// Global bounded queue with backpressure signal
class LogIngestionPipeline {
  constructor(globalCapacity, backlogThreshold) {
    this.globalQueue = new Map();  // teamId -> TeamBuffer
    this.capacity = globalCapacity;
    this.backlogThreshold = backlogThreshold;
    this.currentBacklog = 0;
  }

  // Backpressure: signal when approaching threshold
  isBacklogged() {
    return this.currentBacklog >= this.backlogThreshold;
  }

  ingest(log) {
    if (!this.globalQueue.has(log.teamId)) {
      this.globalQueue.set(log.teamId, new TeamBuffer(log.teamId));
    }

    const buffer = this.globalQueue.get(log.teamId);

    // Always accept ERROR logs
    if (log.severity === 'ERROR') {
      buffer.push(log);
      this.currentBacklog++;
      return true;
    }

    // Under backlog: accept all
    if (!this.isBacklogged()) {
      buffer.push(log);
      this.currentBacklog++;
      return true;
    }

    // Over backlog: deterministic drop policy
    return buffer.tryAppendWithPruning(log, this.backlogThreshold / this.globalQueue.size);
  }
}
```

## Backpressure Signaling

- **Push-based**: Callback/EventEmitter to producers when backlog > 80% threshold
- **Pull-based**: Expose `canAccept()` or `backlogPercentage()` for producers to poll
- **HTTP headers**: X-RateLimit headers (Retry-After, X-Backlog-Level)
- **Circuit breaker**: Temporarily reject with 503 Service Unavailable

## Test Plan

### Unit Tests
1. **Ordering verification**: Confirm per-team logs maintain FIFO order under normal and degraded conditions
2. **Drop policy correctness**: Verify ERROR logs never dropped; INFO/WARN dropped deterministically when over threshold
3. **Backpressure triggers**: Validate signal fires at correct threshold
4. **Sequence integrity**: Ensure seq numbers preserved after pruning

### Integration Tests
1. **High throughput**: Simulate 10x normal load, verify graceful degradation
2. **Burst handling**: Rapid bursts per team, confirm fair buffer management
3. **Recovery**: Backlog clears, verify no log loss or corruption

### Chaos Tests
1. **Producer failure**: Stop producers mid-stream, verify pipeline stability
2. **Memory pressure**: Constrain heap, verify bounded behavior
3. **Ordering stress**: Random severity injection, validate final order

## Why This Question Is Asked
This tests understanding of per-topic ordering, backpressure mechanisms, dynamic topic management, and safe shutdown in a concurrent dispatcher system.

## Key Concepts
- **Bounded backlog and backpressure**: Prevent memory exhaustion by limiting queue depth and signaling producers when buffers are full
- **Per-topic FIFO with ordering guarantees**: Ensure events within each topic maintain publication order
- **Fair scheduling (round-robin)**: Prevent a high-volume topic from starving others
- **Dynamic topic management**: Support on-the-fly topic creation as new device types appear
- **Cancellation and graceful shutdown**: Safely drain pending work without data loss

## Code Example
```go
package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type Event struct {
	Topic   string
	Payload string
}

type TopicQueue struct {
	ch     chan Event
	mu     sync.Mutex
	closed bool
}

type Dispatcher struct {
	globalBacklog chan Event
	topicQueues  map[string]*TopicQueue
	workers      int
	wg           sync.WaitGroup
	mu           sync.RWMutex
	ctx          context.Context
	cancel       context.CancelFunc
}

func NewDispatcher(backlogSize, workers int) *Dispatcher {
	ctx, cancel := context.WithCancel(context.Background())
	d := &Dispatcher{
		globalBacklog: make(chan Event, backlogSize),
		topicQueues:  make(map[string]*TopicQueue),
		workers:      workers,
		ctx:          ctx,
		cancel:       cancel,
	}
	return d
}

func (d *Dispatcher) getOrCreateTopic(topic string) *TopicQueue {
	d.mu.Lock()
	defer d.mu.Unlock()
	if q, ok := d.topicQueues[topic]; ok {
		return q
	}
	q := &TopicQueue{ch: make(chan Event, 100)}
	d.topicQueues[topic] = q
	return q
}

func (d *Dispatcher) Enqueue(e Event) error {
	select {
	case d.globalBacklog <- e:
		return nil
	default:
		return fmt.Errorf("backpressure: global backlog full")
	}
}

func (d *Dispatcher) Start() {
	for i := 0; i < d.workers; i++ {
		d.wg.Add(1)
		go d.worker(i)
	}
	go d.dispatcher()
}

func (d *Dispatcher) dispatcher() {
	for {
		select {
		case <-d.ctx.Done():
			return
		case e := <-d.globalBacklog:
			q := d.getOrCreateTopic(e.Topic)
			select {
			case q.ch <- e:
			default:
				fmt.Printf("backpressure: topic %s full\n", e.Topic)
			}
		}
	}
}

func (d *Dispatcher) worker(id int) {
	defer d.wg.Done()
	for {
		select {
		case <-d.ctx.Done():
			return
		default:
		}
		d.mu.RLock()
		topics := make([]string, 0, len(d.topicQueues))
		for t := range d.topicQueues {
			topics = append(topics, t)
		}
		d.mu.RUnlock()
		if len(topics) == 0 {
			time.Sleep(time.Millisecond)
			continue
		}
		for _, topic := range topics {
			d.mu.RLock()
			q, ok := d.topicQueues[topic]
			d.mu.RUnlock()
			if !ok {
				continue
			}
			select {
			case e := <-q.ch:
				fmt.Printf("worker %d processed: %s -> %s\n", id, e.Topic, e.Payload)
			default:
			}
		}
	}
}

func (d *Dispatcher) Shutdown() {
	d.cancel()
	d.wg.Wait()
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, q := range d.topicQueues {
		close(q.ch)
	}
}

func main() {
	d := NewDispatcher(1000, 3)
	d.Start()

	d.Enqueue(Event{Topic: "temperature", Payload: "25.5"})
	d.Enqueue(Event{Topic: "humidity", Payload: "60%"})
	d.Enqueue(Event{Topic: "temperature", Payload: "26.0"})

	time.Sleep(100 * time.Millisecond)
	d.Shutdown()
	fmt.Println("shutdown complete")
}
```

